int a[N];

int quick(int l,int r){
    int p=a[l],i=l,j=r;
    while(i<j){
        while(j>i && a[j]>p) j--;
        while(i<j && a[i]<=p) i++;
        swap(a[i],a[j]);
    }
    swap(a[l],a[j]);
    return j;
}

void quick_sort(int l,int r){
    if(r<=l) return;
    int mid=quick(l,r);
    quick_sort(l,mid-1);
    quick_sort(mid+1,r);
}
